document.querySelector('.mobile-menu').addEventListener('click',e=>{if(e.target.closest('a')){document.querySelector('.mobile-menu').hidden=true;menu.setAttribute('aria-expanded','false');menu.querySelector('span').textContent='＋';}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.querySelector('.mobile-menu').hidden=true;menu.setAttribute('aria-expanded','false');menu.querySelector('span').textContent='＋';}});
function captureButton(file,label,cls=''){return '<button class="capture-open '+cls+'" type="button" data-enlarge aria-label="'+esc((lang==='ko'?'이미지 확대: ':'Enlarge image: ')+label)+'"><img src="'+asset(file)+'" alt="'+esc(label)+'" loading="lazy"><span class="capture-hint">'+esc(c.expand)+' ↗</span></button>';}
function metdolDiagram(){
 const d=lang==='ko'?{label:'요청한 기기에서 Metdol을 통해 선택한 기기·모델로 작업을 보내고 결과를 받는 연결 구조도',origin:'지금 쓰는 기기',target:'작업을 맡길 기기',model:'모델 · 등록한 도구 · 자료',request:'요청',result:'결과',tag:'연결 구조도',core:'터미널 기반'}:{label:'Connection illustration: a requesting device sends work through Metdol to a selected device and model and receives a result',origin:'Your device',target:'Selected device',model:'Model · tool · source',request:'REQUEST',result:'RESULT',tag:'CONNECTION OVERVIEW',core:'TERMINAL-BASED'};
 return '<div class="connection-illustration" role="img" aria-label="'+esc(d.label)+'"><p class="diagram-kicker">'+esc(d.tag)+'</p><div class="connection-flow"><div class="connection-node"><span class="device-outline" aria-hidden="true"></span><strong>'+esc(d.origin)+'</strong></div><div class="connection-lane" aria-hidden="true"><span>→</span><span>←</span></div><div class="metdol-core"><span>METDOL</span><small>'+esc(d.core)+'</small></div><div class="connection-lane" aria-hidden="true"><span>→</span><span>←</span></div><div class="connection-node"><span class="device-outline" aria-hidden="true"></span><strong>'+esc(d.target)+'</strong><small>'+esc(d.model)+'</small></div></div><div class="connection-legend"><span>→ '+esc(d.request)+'</span><span>← '+esc(d.result)+'</span></div></div>';
}
function visual(p){
 if(p.id==='metdol')return metdolDiagram();
 if(p.id==='moirion')return '<div class="moirion-composition">'+captureButton(p.image,lang==='ko'?'Moirion Mac 작성 화면':'Moirion Mac writing screen','composition-mac')+captureButton(p.phone,lang==='ko'?'Moirion 아이폰의 Apple 기기 내 AI 답변':'Moirion iPhone Apple on-device response','composition-phone')+'</div>';
 if(p.image)return '<button class="capture-open" type="button" data-enlarge aria-label="'+esc((lang==='ko'?'이미지 확대: ':'Enlarge image: ')+p[lang].name)+'"><img src="'+asset(p.image)+'" alt="'+esc(p[lang].caption)+'" loading="lazy"><span class="capture-hint">'+esc(c.expand)+' ↗</span></button>';
 if(p.type==='agent')return '<div class="agent-illustration"><p class="diagram-label">AI TEAM / BOUNDED TASK</p><div>'+ (lang==='ko'?'준비':'Prepare')+' <span>01</span></div><div>'+(lang==='ko'?'검토':'Review')+' <span>02</span></div><div>'+(lang==='ko'?'결과':'Return')+' <span>03</span></div></div><span class="illustration-note">'+(lang==='ko'?'역할 설명 도식':'Role illustration')+'</span>';
 return '<div class="layer-illustration"><span class="layer-top">'+(lang==='ko'?'요청 · 권한':'REQUEST · AUTHORITY')+'</span><span class="layer-core">ARDAMIRE<br>DEFENSE LAYER</span><span class="layer-bottom">'+(lang==='ko'?'근거 · 복구':'EVIDENCE · RECOVERY')+'</span></div><span class="illustration-note">'+(lang==='ko'?'방어 경계 도식':'Boundary illustration')+'</span>';
}
function stage(p){const t=p[lang];return '<div class="stage-visual '+p.type+'">'+visual(p)+'</div><p class="stage-caption">'+esc(t.caption)+'</p>'+(t.mediaNote?'<p class="media-provenance">'+esc(t.mediaNote)+'</p>':'')+'<div class="stage-description"><h3>'+rich(t.title)+'</h3><p>'+esc(t.summary)+'</p><div class="stage-connection"><p class="eyebrow">'+esc(c.connectionLabel)+'</p><p>'+esc(t.connection)+'</p></div>'+link(url(p.id),c.viewDetail+' '+t.name)+'</div>';}
function contact(){return '<section class="contact-section" id="contact"><p class="eyebrow">'+esc(c.contactLabel)+'</p><div><h2>'+rich(c.contactTitle)+'</h2><p>'+esc(c.contactBody)+'</p>'+link('mailto:hello@auxtho.com',c.contactLink)+'</div></section>';}
function film(){return '<section class="film-section" id="walkthrough"><div class="film-copy"><p class="eyebrow">'+esc(c.filmLabel)+'</p><h2>'+rich(c.filmTitle)+'</h2><p>'+esc(c.filmBody)+'</p>'+link(url('auxtho','#verification'),c.filmLink)+'</div><div class="film-box"><video controls playsinline preload="none" poster="'+asset('video-poster.png')+'" aria-label="'+esc(c.filmLabel)+'"><source src="'+asset('walkthrough.mp4')+'" type="video/mp4"></video><p>'+esc(c.filmCaption)+'</p></div></section>';}
function softwareSection(items,sectionId,title,intro,stageId){
const tech=sectionId==='technology';
return '<section class="software-section'+(tech?' technology-section':'')+'" id="'+sectionId+'"><div class="section-heading"><div>'+(tech?'<p class="eyebrow">'+esc(c.technologyLabel)+'</p>':'')+'<h2>'+esc(title)+'</h2></div><p>'+esc(intro)+'</p></div><div class="portfolio-layout"><div class="product-list">'+items.map((p,i)=>'<div class="product-row"><button class="product-select" data-product="'+p.id+'" aria-pressed="'+(i===0)+'" aria-controls="'+stageId+'"><span class="product-number">0'+(i+1)+'</span><span><span class="product-name">'+esc(p[lang].name)+'</span><span class="product-type">'+esc(p[lang].role)+'</span></span></button><a class="product-open" href="'+url(p.id)+'" aria-label="'+esc(c.viewDetail+' '+p[lang].name)+'">↗</a></div><p class="product-purpose">'+esc(p[lang].why)+'</p>').join('')+'</div><div class="product-stage" id="'+stageId+'" aria-live="polite">'+stage(items[0])+'</div></div></section>';
}
