function moirionGallery(kind){
 const screens=moirionScreens[kind],s=screens[0],label=kind==='mac'?(lang==='ko'?'Mac 실제 화면':'Actual Mac screens'):(lang==='ko'?'아이폰 실제 화면':'Actual iPhone screens');
 return '<div class="capture-gallery '+kind+'-gallery" data-gallery="'+kind+'"><div class="gallery-tabs" role="tablist" aria-label="'+esc(label)+'">'+screens.map((x,i)=>'<button id="gallery-'+kind+'-tab-'+i+'" type="button" role="tab" data-gallery-index="'+i+'" aria-selected="'+(i===0)+'" tabindex="'+(i===0?0:-1)+'" aria-controls="gallery-'+kind+'-panel">'+esc(x[lang][0])+'</button>').join('')+'</div><div class="gallery-panel" id="gallery-'+kind+'-panel" role="tabpanel" aria-labelledby="gallery-'+kind+'-tab-0"><div class="gallery-image">'+captureButton(s.file,s[lang][1])+'</div><div class="gallery-copy"><p class="eyebrow">'+esc(label)+' / <span class="gallery-count">01 / '+String(screens.length).padStart(2,'0')+'</span></p><h3>'+esc(s[lang][1])+'</h3><p class="gallery-description">'+esc(s[lang][2])+'</p><p class="gallery-date">'+(lang==='ko'?'2026년 10월 9일 · 영어 화면 · 실제 개발 버전':'9 October 2026 · English UI · actual development build')+'</p></div></div></div>';
}
function moirionMedia(){
 return '<div class="moirion-media"><div class="moirion-gallery-intro">'+bodyParagraphs(c.galleryIntro,'detail-intro')+'</div><p class="media-provenance">'+esc(c.galleryScope)+'</p><h2>'+(lang==='ko'?'Mac에서 기록하고 돌아봅니다':'Room to write on Mac')+'</h2>'+moirionGallery('mac')+'<h2>'+(lang==='ko'?'나의 하루, 아이폰에서도':'Your day, on iPhone')+'</h2>'+moirionGallery('iphone')+'<section class="joint-case"><div><p class="eyebrow">MOIRION × METDOL / '+(lang==='ko'?'2026년 10월 5일':'5 OCT 2026')+'</p><h3>'+(lang==='ko'?'아이폰으로 묻고, 내 Mac의 AI로 답합니다':'From your phone to your paired Mac model')+'</h3><p>'+esc(c.practice2Body)+'</p>'+link(url('metdol'),lang==='ko'?'Metdol 연결 구조 보기':'Explore the Metdol connection')+'</div><figure>'+captureButton('metdol-phone.png',c.jointCapture)+'<figcaption>'+esc(c.jointCapture)+'</figcaption></figure></section></div>';
}
function bindMoirionGalleries(){
 document.querySelectorAll('[data-gallery]').forEach(g=>{
  const kind=g.dataset.gallery,screens=moirionScreens[kind],tabs=[...g.querySelectorAll('[role=tab]')];
  const select=i=>{const s=screens[i];tabs.forEach((b,n)=>{b.setAttribute('aria-selected',String(i===n));b.tabIndex=i===n?0:-1;});g.querySelector('[role=tabpanel]').setAttribute('aria-labelledby','gallery-'+kind+'-tab-'+i);const img=g.querySelector('.gallery-image img');img.src=asset(s.file);img.alt=displayCopy(s[lang][1]);g.querySelector('.gallery-image button').setAttribute('aria-label',(lang==='ko'?'이미지 확대: ':'Enlarge image: ')+displayCopy(s[lang][1]));g.querySelector('h3').textContent=displayCopy(s[lang][1]);g.querySelector('.gallery-description').textContent=displayCopy(s[lang][2]);g.querySelector('.gallery-count').textContent=String(i+1).padStart(2,'0')+' / '+String(screens.length).padStart(2,'0');};
  tabs.forEach((b,i)=>{b.addEventListener('click',()=>select(i));b.addEventListener('keydown',e=>{let n;if(e.key==='ArrowRight')n=(i+1)%tabs.length;if(e.key==='ArrowLeft')n=(i-1+tabs.length)%tabs.length;if(e.key==='Home')n=0;if(e.key==='End')n=tabs.length-1;if(n!==undefined){e.preventDefault();select(n);tabs[n].focus();}});});
 });
}
