'<section class="detail-main" id="workflow"><p class="eyebrow">'+esc(c.detailsLabel)+' / '+esc(t.name)+'</p><h2>'+esc(c.workflowTitle)+'</h2><p class="detail-intro">'+esc(t.workflowIntro)+'</p>'+familyContext(p)+steps(p)+capabilities(p)+productMedia(p)+(p.id==='auxtho'?auxthoBody():verificationRecords(p)+link(external,externalLabel,'line-link')+development(p)+productFaq(p))+
'<div class="product-related"><a href="'+url('','#software')+'">'+esc(c.related)+' ↗</a><a href="mailto:hello@auxtho.com">'+esc(c.contactLink)+' ↗</a></div></section>'+(p.id==='auxtho'?film():'')+contact();
if(p.id==='auxtho')bindTabs();
if(p.id==='moirion')bindMoirionGalleries();
