document.querySelector('.site-footer').innerHTML='<div class="footer-company"><a class="brand" href="'+url()+'"><img src="'+asset('logo-white.svg')+'" alt="Auxtho"></a><p>'+esc(c.footerLine)+'</p><p class="footer-company-name">Auxtho Inc.</p><a class="footer-email" href="mailto:hello@auxtho.com">hello@auxtho.com</a></div><div class="footer-groups"><div class="footer-group"><p class="eyebrow">'+esc(c.footerProductLabel)+'</p><div class="footer-links">'+customerProducts.map(p=>'<a href="'+url(p.id)+'">'+esc(p[lang].name)+'</a>').join('')+'</div></div><div class="footer-group"><p class="eyebrow">'+esc(c.footerTechnologyLabel)+'</p><div class="footer-links">'+technologyProducts.map(p=>'<a href="'+url(p.id)+'">'+esc(p[lang].name)+'</a>').join('')+'</div></div></div><section class="footer-membership" aria-label="'+esc(c.membershipLabel)+'"><div class="footer-brand-lockup"><a class="membership-company" href="'+url()+'"><img src="'+asset('logo-white.svg')+'" alt="Auxtho" width="260" height="74"></a><a class="membership-badge" href="https://www.nvidia.com/en-us/startups/" aria-label="'+esc(c.membershipLinkLabel)+'"><img src="'+asset('nvidia-inception-member.svg')+'" alt="'+esc(c.membershipAlt)+'" width="152" height="66" loading="lazy"></a></div><div class="membership-copy"><p class="membership-description">'+footerLiteral(c.membership)+'</p><p class="membership-trademark">'+footerLiteral(c.membershipTrademark)+'</p></div></section><div class="footer-information"><p class="footer-copyright">'+footerLiteral(c.footerCopyright)+'</p><nav class="footer-links" aria-label="'+esc(c.footerInfoLabel)+'">'+c.footerInfoLinks.map(x=>'<a href="'+x[1]+'">'+footerLiteral(x[0])+'</a>').join('')+'</nav></div>';
